#include "termio/Clipboard.hpp"
#include <iostream>
using namespace batbox;
int main(){const std::string bytes((std::istreambuf_iterator<char>(std::cin)),{});Json all=Json::array();for(const auto& item:value::parse(bytes)){event_loop::Loop loop;Json calls=Json::array(),trace=Json::array(),env=item.value("env",Json::object());std::string terminal=item.value("terminal","");std::map<std::string,std::size_t> counts;
 termio::ClipboardServices services;services.environment={item.at("platform"),[&](const std::string& key)->std::optional<std::string>{if(!env.contains(key)||env[key].is_null())return {};return env[key].get<std::string>();}};services.terminalName=[&]{return terminal;};
 services.execFileNoThrow=[&](const std::string& file,const std::vector<std::string>& args,const process::ExecOptions& opts){calls.push_back(Json::array({file,args,Json{{"input",*opts.input},{"useCwd",*opts.useCwd},{"timeout",*opts.timeout}}}));const auto n=counts[file]++;const auto codes=item.contains("codes")&&item.at("codes").contains(file)?item.at("codes").at(file):Json::array({0});event_loop::Deferred<process::ExecResult> result(loop);process::ExecResult value;value.code=codes.at(std::min(n,codes.size()-1));result.resolve(value);return result;};
 termio::ClipboardModule module(loop,services);
 for(const auto& op:item.at("steps")){const auto kind=op.at("op").get<std::string>();if(kind=="copy"){module.setClipboard(op.at("text")).then([&](const std::string* value,const std::exception_ptr& e){if(e)std::rethrow_exception(e);trace.push_back(Json::array({"copy",*value}));});trace.push_back("sync");}else if(kind=="native")module.copyIndigenous(op.at("text"));else if(kind=="path")trace.push_back(module.getClipboardPath());else if(kind=="wrap")trace.push_back(module.wrapForMultiplexer(op.at("text")));else if(kind=="reset")module.resetLinuxCopyStash();else if(kind=="env")env[op.at("key").get<std::string>()]=op.at("value");else if(kind=="terminal")terminal=op.at("value");else if(kind=="tick"){loop.runReady();trace.push_back("tick");}}
 loop.runReady();all.push_back(Json{{"calls",calls},{"trace",trace}});}std::cout<<value::stringify(all)<<'\n';}
